package com.studybuddy.model;

import java.time.LocalDateTime;

/**
 * One row of a group's activity feed. Generated by the system from real actions
 * (joined, proposed, confirmed). Never typed by a user.
 */
public class ActivityEvent {

    private final StudyGroup group;
    private final ActivityType type;
    private final String text;
    private final LocalDateTime timestamp;

    /** Creates a feed row for one real action in a group. */
    public ActivityEvent(StudyGroup group, ActivityType type, String text, LocalDateTime timestamp) {
        this.group = group;
        this.type = type;
        this.text = text;
        this.timestamp = timestamp;
    }

    /** Returns the group this event belongs to. */
    public StudyGroup getGroup() {
        return group;
    }

    /** Returns the kind of action that generated this event. */
    public ActivityType getType() {
        return type;
    }

    /** Returns the display text of the feed row. */
    public String getText() {
        return text;
    }

    /** Returns when the action happened. */
    public LocalDateTime getTimestamp() {
        return timestamp;
    }

    /** Returns a short description of this event for logs and debugging. */
    @Override
    public String toString() {
        return "ActivityEvent[" + type + " " + text + "]";
    }
}
